//! Form naming preserves trusted native editing and submission data.
use super::*;
struct Fixture(std::path::PathBuf);impl Drop for Fixture{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
fn node(app:&App,id:&str)->usize{let mut pending=vec![0];while let Some(n)=pending.pop(){if app.document.dom_attr(n,"id").is_some_and(|v|v.raw_units().is_none()&&v.as_str()==id){return n;}pending.extend(app.document.nodes[n].children.iter().rev().copied());}panic!("connected node {id}")}
fn click(app:&mut App,node:usize){let r=app.page.controls.iter().find(|r|r.node==node).unwrap();let(x,y)=(r.x+r.width/2,app.content_top()+r.y+r.height/2-app.scroll);app.pointer_down(x,y,false);app.pointer_up(x,y);}

fn post(app:&App,owner:usize)->Result<String,String>{let s=app.forms.submit_request(&app.document,owner,None,&app.location,&app.base_location)?;let crate::http::Request::FormPost{body,..}=s.request else{return Err("Expected POST".into())};Ok(String::from_utf8(body).unwrap())}
#[test]
fn form_no_validate_actual_app_pointer_toggles_required_bypass_and_preserves_editor_paint_links(){
 let file=Fixture(std::env::temp_dir().join(format!("chezcat-app-form-no-validate-{}.html",std::process::id())));
 std::fs::write(&file.0,r#"<!doctype html><style>body{margin:0;background:white}button{position:absolute;top:20px;width:130px;height:32px}#allow{left:20px}#block{left:170px}#area{position:absolute;left:20px;top:80px;width:180px;height:30px}#checkbox{position:absolute;left:20px;top:140px}#neighbor{position:absolute;left:220px;top:100px;width:160px;height:30px}#stable{position:absolute;left:420px;top:100px}#paint{position:absolute;left:420px;top:160px;width:40px;height:30px;background:#114455}#paint.done{background:#cc2244}</style><form id=form method=post action=https://form-no-validate.test/submit><input id=area name=q required><input id=checkbox type=checkbox name=checked required></form><input id=neighbor value=neighbor><button id=allow>Allow</button><button id=block>Block</button><a id=stable href=#destination>Go</a><div id=paint></div><div id=destination></div><script>var x=document.getElementById('form'),editor=document.getElementById('area'),events=0;editor.oninput=function(e){if(!e.isTrusted)throw 'untrusted input';events++;};document.getElementById('allow').onclick=function(e){if(!e.isTrusted||events!==4||editor.value!=='A😀ZQ')throw 'trusted editing';x.noValidate=true;if(x.noValidate!==true||x.getAttributeNS(null,'novalidate')!=='')throw 'allow';document.getElementById('paint').className='done';document.title='Validation bypass enabled';};document.getElementById('block').onclick=function(e){if(!e.isTrusted||events!==4||editor.value!=='A😀ZQ')throw 'retained editing';x.noValidate=false;if(x.noValidate!==false||x.hasAttribute('novalidate'))throw 'block';document.getElementById('paint').className='';document.title='Validation bypass disabled';};</script>"#).unwrap();
 let mut app=App::new();app.resize(640,480);app.set_javascript_enabled(true);app.open(&file.0);assert!(!app.failed&&!app.is_loading(),"{}",app.status);let area=node(&app,"area");let owner=node(&app,"form");let checkbox=node(&app,"checkbox");let stable=node(&app,"stable");let allow=node(&app,"allow");let block=node(&app,"block");let neighbor=node(&app,"neighbor");let identity=(app.raw.clone(),app.location.clone(),app.script_epoch);let initial=app.draw();assert!(post(&app,owner).is_err());click(&mut app,area);for ch in ['A','😀','Z','Q']{app.text_input(ch);}assert!(post(&app,owner).is_err(),"unchecked required checkbox must still block");let e=&app.forms.controls[&area].value;let selected=(e.cursor,e.anchor,e.offset);app.forms.script_set_value(neighbor,"edited neighbor").unwrap();{let e=&mut app.forms.controls.get_mut(&neighbor).unwrap().value;e.cursor=5;e.anchor=2;e.offset=1;}
 click(&mut app,allow);assert_eq!(app.document.title,"Validation bypass enabled");assert_eq!(post(&app,owner).unwrap(),"q=A%F0%9F%98%80ZQ");assert!(!app.forms.controls[&checkbox].checked);assert!(app.forms.controls[&checkbox].required);let painted=app.draw();assert_eq!(painted.pixels[(app.content_top()+170)as usize*painted.width+430],0xcc2244);let e=&app.forms.controls[&area].value;assert_eq!((e.cursor,e.anchor,e.offset),selected);assert_eq!(e.text(),"A😀ZQ");assert!(app.forms.controls[&area].dirty_value);let r=app.page.controls.iter().find(|r|r.node==area).unwrap();let(left,top,right,bottom)=(r.x.max(0)as usize,(app.content_top()+r.y-app.scroll).max(0)as usize,(r.x+r.width).min(painted.width as i32)as usize,(app.content_top()+r.y-app.scroll+r.height).min(painted.height as i32)as usize);assert!((top..bottom).any(|y|initial.pixels[y*initial.width+left..y*initial.width+right]!=painted.pixels[y*painted.width+left..y*painted.width+right]),"actual typed editor paint");click(&mut app,block);assert_eq!(app.document.title,"Validation bypass disabled");assert!(post(&app,owner).is_err());let e=&app.forms.controls[&neighbor].value;assert_eq!((e.text(),e.cursor,e.anchor,e.offset),("edited neighbor".into(),5,2,1));assert_eq!(app.page.link_node_at(430,110),Some(stable));assert_eq!((app.raw.clone(),app.location.clone(),app.script_epoch),identity);assert_eq!(app.scripting.as_ref().unwrap().error_count(),0,"{}",app.scripting.as_ref().unwrap().report());
}
